package main

import "encoding/base64"

// Called only on the native UI thread. Recent WebView2 runtimes report
// NavigateToString's initial navigation as a data URI; the resulting document
// still has about:blank as its source. Allow only our exact generated bytes,
// once, while retaining compatibility with runtimes that report about:blank.
// No other data URI, iframe, or later navigation may acquire Go bindings.
type nativeNavigationGate struct {
	loaded         bool
	initialDataURI string
}

func newNativeNavigationGate(html string) nativeNavigationGate {
	return nativeNavigationGate{initialDataURI: "data:text/html;charset=utf-8;base64," + base64.StdEncoding.EncodeToString([]byte(html))}
}

func (g *nativeNavigationGate) Allow(uri string, frame bool) bool {
	if frame || g.loaded || (uri != "about:blank" && (g.initialDataURI == "" || uri != g.initialDataURI)) {
		return false
	}
	g.loaded = true
	return true
}
